<?php
use App\Accounts\DeviceAuth;
use App\Domain\{Access,Failure};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,RateLimiter,Route};
Route::get('/api/me',fn(Request $r)=>['user'=>DeviceAuth::safe(Access::user((int)$r->session()->get('uid'))),'csrf_token'=>csrf_token(),'ws_url'=>config('classroom.ws_url')]);
Route::post('/api/login',fn(Request $r)=>app(DeviceAuth::class)->login($r,$r->validate(['student_id'=>'required|string|max:100','password'=>'required|string|max:200','remember'=>'sometimes|boolean'])));
Route::post('/api/password',fn(Request $r)=>app(DeviceAuth::class)->changePassword($r,$r->validate(['password'=>'required|string|min:10|max:200','current_password'=>'sometimes|string|max:200'])));
Route::post('/api/logout',function(Request $r){app(DeviceAuth::class)->logoutDevice($r);return ['csrf_token'=>csrf_token()];});
Route::post('/api/logout-all',function(Request $r){$u=Access::user((int)$r->session()->get('uid'));if(!$u)throw new Failure('login_required',401);$v=$r->validate(['current_password'=>'required|string|max:200']);if(!Hash::check($v['current_password'],$u->password))throw new Failure('invalid_credentials',401);DeviceAuth::revokeUser((int)$u->id);app(DeviceAuth::class)->logoutDevice($r);return ['csrf_token'=>csrf_token()];});
Route::post('/api/reauth',function(Request $r){$u=Access::user((int)$r->session()->get('uid'));Access::member($u);$key='reauth:'.$u->id;if(RateLimiter::tooManyAttempts($key,5))throw new Failure('login_rate_limited',429);RateLimiter::hit($key,60);$v=$r->validate(['password'=>'required|string|max:200']);if(!Hash::check($v['password'],$u->password))throw new Failure('invalid_credentials',401);RateLimiter::clear($key);$r->session()->put(['reauth_until'=>time()+900,'reauth_at'=>time()]);return ['reauth_until'=>now()->addSeconds(900)->toIso8601String()];});
Route::get('/api/devices',function(Request $r){$u=Access::user((int)$r->session()->get('uid'));Access::member($u);return ['devices'=>DB::table('login_devices')->where('user_id',$u->id)->whereNull('revoked_at')->where('expires_at','>',now())->select('id','user_agent','created_at','last_used_at','expires_at')->orderByDesc('last_used_at')->get()->map(fn($d)=>[...(array)$d,'current'=>$r->session()->get('device_id')===$d->id])];});
Route::delete('/api/devices/{device}',function(Request $r,string $device){$u=Access::user((int)$r->session()->get('uid'));Access::member($u);$d=DB::table('login_devices')->where('id',$device)->where('user_id',$u->id)->first();if(!$d)throw new Failure('device_unavailable',404);DB::transaction(function()use($device){DB::table('login_devices')->where('id',$device)->update(['revoked_at'=>now()]);DeviceAuth::discardSessions(DB::table('sessions')->where('device_id',$device)->pluck('id')->all());});if($r->session()->get('device_id')===$device)app(DeviceAuth::class)->logoutDevice($r);return ['revoked'=>true,'csrf_token'=>csrf_token()];})->whereUuid('device');
